package alcaldedigital.mision8;

import alcaldedigital.cliente.mision8.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class HistoriaOchoTest {
 private MotorOcho mutacion(int candidato){var m=new MotorOcho(MisionOchoTest.antecedentes(candidato,false),1,1,0,false,1);MisionOchoTest.cerrarConversacion(m);MisionOchoTest.cerrarConversacion(m);for(int i=0;i<3;i++)m.auditar(i,true);m.votar(0,candidato);MisionOchoTest.cerrarConversacion(m);assertEquals(MotorOcho.Escena.MUTACION,m.escena);return m;}
 private void irAccion(MotorOcho m,HistoriaOcho.Accion accion){int limite=20;while(HistoriaOcho.actual(m).accion()!=accion&&limite-->0){var l=HistoriaOcho.actual(m);for(int t=0;t<Math.max(l.duracion(),200);t++)m.paso();m.avanzar();}assertEquals(accion,HistoriaOcho.actual(m).accion());}
 @Test void dialogosEsperanEntradaYMuestranUnaIntervencion(){var m=new MotorOcho(MisionOchoTest.antecedentes(0,false),1,1,0,false,2);for(int i=0;i<1200;i++)m.paso();assertEquals(MotorOcho.Escena.OBRA,m.escena);assertEquals(0,m.lineaDialogo);assertEquals("PERIODISTA",HistoriaOcho.actual(m).quien());m.avanzar();assertEquals(1,m.lineaDialogo);assertEquals("INFLUENCER",HistoriaOcho.actual(m).quien());assertEquals("",m.textoVisible());m.avanzar();assertTrue(m.textoCompleto());assertEquals(1,m.lineaDialogo);}
 @Test void noSePuedeSaltarLaObraNiLaInyeccion(){var m=mutacion(0);irAccion(m,HistoriaOcho.Accion.INYECTAR);for(int i=0;i<10;i++)m.avanzar();assertFalse(m.inyectado);assertEquals(HistoriaOcho.Accion.INYECTAR,HistoriaOcho.actual(m).accion());for(int i=0;i<35;i++)m.paso();assertTrue(m.inyectado);m.avanzar();m.avanzar();assertEquals(HistoriaOcho.Accion.INYECTAR,HistoriaOcho.actual(m).accion());}
 @Test void palomoVuelaHastaCadaCandidatoYLaAgujaHaceContacto(){for(int candidato=0;candidato<4;candidato++){final int elegido=candidato;var m=mutacion(candidato);irAccion(m,HistoriaOcho.Accion.VUELO);var inicio=EscenografiaOcho.palomo(m);for(int t=0;t<120;t++)m.paso();var fin=EscenografiaOcho.palomo(m);assertTrue(Math.hypot(inicio.x()-fin.x(),inicio.y()-fin.y())>100);assertEquals(EscenografiaOcho.candidato(candidato).x()+67,fin.x(),.001);m.avanzar();m.avanzar();assertEquals(HistoriaOcho.Accion.INYECTAR,HistoriaOcho.actual(m).accion());for(int t=0;t<35;t++)m.paso();assertEquals(EscenografiaOcho.contacto(m),EscenografiaOcho.puntaAguja(m));assertTrue(m.inyectado);assertTrue(m.historial.stream().anyMatch(x->x.equals("Palomo inyectó al candidato elegido: "+elegido)));}}
 @Test void pausaYGuardadoConservanLaInyeccionSinRepetirla(){var m=mutacion(3);irAccion(m,HistoriaOcho.Accion.INYECTAR);for(int t=0;t<34;t++)m.paso();m.pausar(true);var antes=m.capturar();for(int t=0;t<100;t++)m.paso();assertEquals(antes,m.capturar());var copia=MotorOcho.restaurar(antes);m.pausar(false);copia.pausar(false);for(int t=0;t<80;t++){m.paso();copia.paso();}assertEquals(m.capturar(),copia.capturar());assertEquals(1,m.historial.stream().filter(x->x.startsWith("Palomo inyectó")).count());}
 @Test void lasCuatroPlazasSonDistintasYSinSolaparse(){for(int i=0;i<4;i++){var sitio=EscenografiaOcho.candidato(i);assertEquals(280,sitio.y());assertTrue(sitio.x()>250&&sitio.x()<1150);if(i>0)assertTrue(sitio.x()-EscenografiaOcho.candidato(i-1).x()>=180);}}
 @Test void epilogoRecuperaAlElegidoYNeutralizaAPalomoAntesDelFinal(){var m=MisionOchoTest.combate(2,false,1,1,0);m.fase=5;m.vidaJefe=0;m.paso();assertEquals(MotorOcho.Escena.EPILOGO,m.escena);assertFalse(m.candidatoRecuperado);assertFalse(m.palomoNeutralizado);MisionOchoTest.cerrarConversacion(m);assertEquals(MotorOcho.Escena.FINAL,m.escena);assertTrue(m.candidatoRecuperado);assertTrue(m.palomoNeutralizado);}
 @Test void conversacionesNoContienenVariosHablantesEnUnBloque(){var m=mutacion(1);for(var escena:new MotorOcho.Escena[]{MotorOcho.Escena.OBRA,MotorOcho.Escena.REVELACION,MotorOcho.Escena.ESCRUTINIO,MotorOcho.Escena.MUTACION,MotorOcho.Escena.EPILOGO}){m.escena=escena;for(var l:HistoriaOcho.lineas(m)){assertFalse(l.quien().isBlank());assertFalse(l.texto().contains("\n"));assertTrue(l.texto().length()<200);}}}
}
